import type { APIRoute } from "astro";
import { topicErrorResponse } from "@/lib/topics/errors";
import { readJson, requireSession } from "@/lib/topics/http";
import { createTopic } from "@/lib/topics/repository";
import { createTopicInput } from "@/lib/topics/schemas";

// Creates a draft topic; subtopics are generated by a separate call.
export const POST: APIRoute = async (context) => {
  const session = requireSession(context);
  if (session instanceof Response) return session;

  const input = await readJson(context.request, createTopicInput);
  if (input instanceof Response) return input;

  const created = await createTopic(session.supabase, input);
  if (!created.ok) return topicErrorResponse(created.code);
  return Response.json({ data: { id: created.value } }, { status: 201 });
};
